canvas.onpointermove=e=>{const old=pointers.get(e.pointerId);if(!old||!ready)return;const dx=e.clientX-old.x,dy=e.clientY-old.y;if(dx===0&&dy===0)return;explore();pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===1){viewer.yaw-=dx*.008;viewer.pitch=Math.max(-1.4,Math.min(1.4,viewer.pitch+dy*.008));}else{const [a,b]=[...pointers.values()],gap=Math.hypot(a.x-b.x,a.y-b.y);if(pinch>0&&gap>0)viewer.distance=Math.max(MIN_DISTANCE,Math.min(1e9,viewer.distance*pinch/gap));pinch=gap;}};
for(const name of ['onpointerup','onpointercancel','onlostpointercapture'])canvas[name]=e=>{pointers.delete(e.pointerId);pinch=0;};
canvas.addEventListener('wheel',e=>{e.preventDefault();if(!ready)return;explore();viewer.distance=Math.max(MIN_DISTANCE,Math.min(1e9,viewer.distance*Math.exp(e.deltaY*.001)));},{passive:false});
canvas.onkeydown=e=>{if(!ready||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','-'].includes(e.key))return;e.preventDefault();explore();if(e.key==='ArrowLeft')viewer.yaw-=.1;if(e.key==='ArrowRight')viewer.yaw+=.1;if(e.key==='ArrowUp')viewer.pitch=Math.min(1.4,viewer.pitch+.1);if(e.key==='ArrowDown')viewer.pitch=Math.max(-1.4,viewer.pitch-.1);if(e.key==='+')viewer.distance=Math.max(MIN_DISTANCE,viewer.distance/1.1);if(e.key==='-')viewer.distance=Math.min(1e9,viewer.distance*1.1);};
document.addEventListener('visibilitychange',()=>{if(document.hidden)pause();last=0;accumulator=0;pointers.clear();pinch=0;});$('space').addEventListener('webglcontextlost',e=>{e.preventDefault();fail(Error('Graphics context lost. Reload to restart.'));});

async function start(){try{data=validate(JSON.parse(new TextDecoder().decode(Uint8Array.from(atob(RECORDED_SEQUENCE),c=>c.charCodeAt(0)))));const response=await fetch('nbody.wasm');if(!response.ok)throw Error(`Wasm download failed (${response.status}).`);wasm=(await WebAssembly.instantiate(await response.arrayBuffer(),{})).instance.exports;gpu=new GravityGPU(canvas);gpu.inertStructure=new InertStructure(gpu);gpu.lobeform=new LobeformSkin(gpu);ready=true;prepare();$('status').textContent='Eigenbeing · animation loaded';$('pause').disabled=false;$('restart').disabled=false;$('fitScreen').disabled=false;
 window.nbodyPlayer={gpu,restart:prepare,advance,get ready(){return ready;},get playing(){return playing;},get time(){return stepIndex*DT;},get duration(){return realTime(data.maxTime);},get actions(){return executed.map(e=>({...e}));},get viewer(){return {...viewer,focus:[...viewer.focus]};},get camera(){cameraBasis();return {yaw,pitch,distance,sceneYaw,scenePitch,truck,pedestal,mode:cameraMode,tracked,focus:[...focus],basis:Array.from(viewBasis)};}};
 requestAnimationFrame(frame);}catch(e){fail(e);}}
start();
